name\": \"azure-blob-crud-sample\",\r\n  \"version\": \"1.0.0\",\r\n  \"private\": true,\r\n  \"type\": \"module\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc -p .\",\r\n    \"start\": \"node .\\\\dist\\\\index.js\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/core-rest-pipeline\": \"1.23.0\",\r\n    \"@azure/identity\": \"4.13.1\",\r\n    \"@azure/storage-blob\": \"12.31.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"25.6.0\",\r\n    \"typescript\": \"6.0.3\"\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport { RestError } from \"@azure/core-rest-pipeline\";\r\nimport { BlobServiceClient } from \"@azure/storage-blob\";\r\n\r\nconst containerName = \"my-container\";\r\nconst blobName = \"greeting.txt\";\r\nconst blobContent = \"Hello Azure!\";\r\n\r\nfunction getRequiredEnvVar(name: string): string {\r\n  const value = process.env[name];\r\n\r\n  if (!value) {\r\n    throw new Error(`Missing required environment variable: ${name}`);\r\n  }\r\n\r\n  return value;\r\n}\r\n\r\nfunction createBlobServiceClient(): BlobServiceClient {\r\n  const accountName = getRequiredEnvVar(\"AZURE_STORAGE_ACCOUNT_NAME\");\r\n  const accountUrl = `https://${accountName}.blob.core.windows.net`;\r\n  const credential = new DefaultAzureCredential();\r\n\r\n  return new BlobServiceClient(accountUrl, credential);\r\n}\r\n\r\nasync function streamToString(\r\n  readableStream: NodeJS.ReadableStream | undefined,\r\n): Promise\u003cstring\u003e {\r\n  if (!readableStream) {\r\n    throw new Error(\"The download response did not include a readable stream.\");\r\n  }\r\n\r\n  return await new Promise\u003cstring\u003e((resolve, reject) =\u003e {\r\n    const chunks: Buffer[] = [];\r\n\r\n    readableStream.on(\"data\", (chunk) =\u003e {\r\n      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));\r\n    });\r\n\r\n    readableStream.on(\"end\", () =\u003e {\r\n      resolve(Buffer.concat(chunks).toString(\"utf-8\"));\r\n    });\r\n\r\n    readableStream.on(\"error\", reject);\r\n  });\r\n}\r\n\r\nfunction logAzureError(error: RestError): void {\r\n  console.error(\"Azure request failed.\");\r\n  console.error(`Status code: ${error.statusCode ?? \"unknown\"}`);\r\n  console.error(`Error code: ${error.code ?? \"unknown\"}`);\r\n  console.error(`Message: ${error.message}`);\r\n\r\n  const requestId = error.response?.headers.get(\"x-ms-request-id\");\r\n  if (requestId) {\r\n    console.error(`Request ID: ${requestId}`);\r\n  }\r\n}\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  const blobServiceClient = createBlobServiceClient();\r\n  const containerClient = blobServiceClient.getContainerClient(containerName);\r\n  const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n\r\n  // Use a dedicated container for this sample because it deletes the container at the end.\r\n  const createContainerResult = await containerClient.createIfNotExists();\r\n  console.log(\r\n    createContainerResult.succeeded\r\n      ? `Created container \"${containerName}\".`\r\n      : `Container \"${containerName}\" already exists.`,\r\n  );\r\n\r\n  await blockBlobClient.upload(blobContent, Buffer.byteLength(blobContent));\r\n  console.log(`Uploaded \"${blobName}\" with content: \"${blobContent}\"`);\r\n\r\n  console.log(\"Blobs in the container:\");\r\n  for await (const blob of containerClient.listBlobsFlat()) {\r\n    console.log(`- ${blob.name}`);\r\n  }\r\n\r\n  const downloadResponse = await blockBlobClient.download();\r\n  const downloadedContent = await streamToString(\r\n    downloadResponse.readableStreamBody,\r\n  );\r\n  console.log(`Downloaded content: ${downloadedContent}`);\r\n\r\n  await blockBlobClient.delete();\r\n  console.log(`Deleted blob \"${blobName}\".`);\r\n\r\n  await containerClient.delete();\r\n  console.log(`Deleted container \"${containerName}\".`);\r\n}\r\n\r\nmain().catch((error: unknown) =\u003e {\r\n  if (error instanceof RestError) {\r\n    logAzureError(error);\r\n  } else if (error instanceof Error) {\r\n    console.error(error.message);\r\n  } else {\r\n    console.error(\"Unexpected error:\", error);\r\n  }\r\n\r\n  process.exitCode = 1;\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2022\",\r\n    \"module\": \"NodeNext\",\r\n    \"moduleResolution\": \"NodeNext\",\r\n    \"outDir\": \"dist\",\r\n    \"rootDir\": \"src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"skipLibCheck\": true,\r\n    \"types\": [\r\n      \"node\"\r\n    ]\r\n  },\r\n  \"include\": [\r\n    \"src/**/*.ts\"\r\n  ]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.)\r\n4. **Error Handling** — Are errors handled properly? Retries? Timeouts?\r\n5. **Code Quality** — Clean, readable, well-structured code?\r\n\r\n## Prompt-Specific Criteria\r\n\r\nIn addition to general criteria, evaluate each prompt-specific criterion listed in the \"Prompt-Specific Evaluation Criteria\" section (if provided). Each criterion is either MET (passed) or NOT MET (failed).\r\n\r\n## Scoring\r\n\r\nFor EACH criterion (general + prompt-specific), determine:\r\n- **passed**: true